DROP TABLE IF EXISTS `grns`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `grns` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `grn_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `grn_date` date NOT NULL,
  `grn_type` enum('po','supplier','direct') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'po',
  `purchase_id` bigint unsigned DEFAULT NULL,
  `supplier_id` bigint unsigned DEFAULT NULL,
  `warehouse_id` bigint unsigned NOT NULL,
  `challan_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `challan_date` date DEFAULT NULL,
  `sub_total` decimal(12,2) NOT NULL DEFAULT '0.00',
  `discount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `total_qty` decimal(12,2) NOT NULL DEFAULT '0.00',
  `total_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `paid_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `fund_account_id` bigint unsigned DEFAULT NULL,
  `is_closed` tinyint NOT NULL DEFAULT '0',
  `received_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `note` text COLLATE utf8mb4_unicode_ci,
  `status` enum('active','deactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_by` bigint unsigned DEFAULT '1',
  `updated_by` bigint unsigned DEFAULT '1',
  `created_ip` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT '1',
  `updated_ip` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT '1',
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `grns_grn_no_unique` (`grn_no`),
  KEY `grns_purchase_id_index` (`purchase_id`),
  KEY `grns_supplier_id_index` (`supplier_id`),
  KEY `grns_warehouse_id_index` (`warehouse_id`),
  KEY `grns_fund_account_id_index` (`fund_account_id`)
) ENGINE=InnoDB AUTO_INCREMENT=99 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

