  `brand` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `model_no` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image` varchar(225) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `warranty_type` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `warranty_period` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unit_id` int NOT NULL,
  `opening_qty` int DEFAULT NULL,
  `reorder_level` decimal(12,2) NOT NULL DEFAULT '0.00',
  `warranty_months` int DEFAULT NULL,
  `useful_life_years` decimal(5,2) DEFAULT '5.00',
  `depreciation_method` enum('straight_line','reducing_balance','none') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'straight_line',
  `depreciation_rate` decimal(5,2) DEFAULT '20.00',
  `salvage_value` decimal(12,2) NOT NULL DEFAULT '0.00',
  `account_id` bigint unsigned DEFAULT NULL,
  `is_serialized` tinyint NOT NULL DEFAULT '0',
  `opening_rate` decimal(8,2) DEFAULT NULL,
