INSERT INTO `notices` VALUES (16,'Scheduled System Maintenance','scheduled-system-maintenance',21,'2024-10-07','2024-10-09','content',NULL,'<p><strong>Date:</strong>&nbsp;[Insert Date]<br />\r\n<strong>Time:</strong>&nbsp;[Insert Time]<br />\r\n<strong>Duration:</strong>&nbsp;Approximately [Insert Duration]</p>\r\n\r\n<p><strong>Attention Team,</strong></p>\r\n\r\n<p>Please be informed that we will be performing scheduled system maintenance on [insert date] from [insert start time] to [insert end time]. During this period, access to our software applications and internal systems may be limited or temporarily unavailable.</p>\r\n\r\n<p>This maintenance is essential for improving system performance and ensuring the security and reliability of our services. We recommend that you save your work and log out of relevant systems before the maintenance window begins.</p>\r\n\r\n<p>Thank you for your understanding as we work to enhance our software capabilities.</p>\r\n\r\n<p>Best regards,<br />\r\n[Your Name]<br />\r\n[Your Position]<br />\r\n[Company Name]</p>',1,'active','2024-10-08 03:40:05','2024-10-08 03:40:05','Nogor Solutions Limited','221.120.98.178',NULL,NULL),(17,'HR Policy Update','hr-policy-update',22,'2024-10-08','2024-10-09','file','upload/notice/241008094128-9737events.pdf',NULL,2,'active','2024-10-08 03:41:28','2024-10-08 03:41:28','Nogor Solutions Limited','221.120.98.178',NULL,NULL),(18,'fgfdgfddsfds','fgfdgfd',21,'2025-03-04',NULL,'file','upload/notice/250303012620-4431pastPresident.pdf',NULL,3,'active','2025-03-03 07:25:53','2025-03-03 07:26:20','Nogor Solutions Limited','221.120.98.178','Nogor Solutions Limited','221.120.98.178');
